function matchesSparkling(product:Product,filter:SparklingFilter){return filter==="all"||(filter==="STILL"?!product.sparklingType:product.sparklingType===filter)}
function isLegacySparklingColor(value:string){return /^(musujące|musujace|sparkling)$/i.test(value.trim())}
function sparklingValue(value:SparklingType,lang:Lang){return value==="NATURALLY_SPARKLING"?(lang==="pl"?"Naturalnie musujące":"Naturally sparkling"):(lang==="pl"?"Musujące":"Sparkling")}
function productWineColor(product:Product){return product.wineColor||(!product.id?product.kind:undefined)}
function beerStyleKey(product:Product):Exclude<BeerStyleFilter,"all">{const text=[product.attributes?.beerStyle,product.pl,product.en,product.descPl,product.descEn].filter(Boolean).join(" ").normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("pl");if(/\bipa\b|india pale ale/.test(text))return"ipa";if(/pszen|witbier|blanche|weizen/.test(text))return"wheat";if(/porter|stout|guinness/.test(text))return"stout";if(/lager|bosman|mastne/.test(text))return"lager";if(/\bale\b|blonde|grimbergen/.test(text))return"ale";if(/somersby|hardmade|cydr|smakow/.test(text))return"flavoured";return"other"}
function isZeroBeer(product:Product){return /^0(?:[,.]0)?\s*%/.test(product.attributes?.alcoholPercentage?.trim()||"")||/\bzero\b|bezalkohol|(?:^|\s)0(?:[,.]0)?\s*%/.test(`${product.pl} ${product.en}`.toLocaleLowerCase("pl"))}
function isDraughtBeer(product:Product){return /(?:bosman|guin+ess)[_\s-]*(?:duże|duze|małe|male)\b/i.test(`${product.pl} ${product.en}`)}
function cakePresentation(product:Product,lang:Lang){const name=`${product.pl} ${product.en}`.normalize("NFD").replace(/[\u0300-\u036f]/g,"").toLocaleLowerCase("pl");const options:Array<[RegExp,string,string,string,string]>=[[/royal\s+carmel/,"Karmel · czekolada · orzech laskowy","Caramel · chocolate · hazelnut","Aksamitny krem, trzy rodzaje czekolady i chrupiąca prażynka…","Silky cream, three kinds of chocolate and a crisp praline layer…"],[/szarlot|apple pie/,"Jabłka · krucha klasyka","Apples · a pastry classic","Klasyczny wypiek z jabłkami — dobry kompan do espresso lub herbaty…","A classic apple bake — a lovely match for espresso or tea…"],[/sernik bask|basque cheesecake/,"Kremowy · karmelizowany","Creamy · caramelised","Kremowa klasyka z charakterystycznie wypieczonym wierzchem…","A creamy classic with its distinctive deeply baked top…"],[/palon.*bial.*czekolad|roasted white chocolate/,"Palona biała czekolada","Roasted white chocolate","Wyrazista palona biała czekolada w eleganckiej tortowej odsłonie…","Roasted white chocolate in an elegant cake interpretation…"],[/slon.*karmel|salted caramel/,"Słony karmel","Salted caramel","Małe ciastko z wyraźną nutą słonego karmelu…","A small pastry with a distinctive salted-caramel note…"],[/brownie/,"Brownie · biała czekolada · owoce","Brownie · white chocolate · fruit","Czekoladowe brownie, biała czekolada i owocowe wykończenie…","Chocolate brownie, white chocolate and a fruity finish…"],[/tarta cytryn|lemon tart/,"Cytryna · beza włoska","Lemon · Italian meringue","Cytrynowa świeżość zwieńczona lekko opaloną bezą włoską…","Bright lemon finished with lightly toasted Italian meringue…"],[/cynamonk|cinnamon/,"Cynamon · miękki wypiek","Cinnamon · soft pastry","Cynamonowy wypiek stworzony do filiżanki dobrej kawy…","A cinnamon bake made for a fine cup of coffee…"],[/maliniank|raspber/,"Maliny · owocowa słodycz","Raspberry · fruity sweetness","Owocowa propozycja z malinowym charakterem…","A fruit-led bake with a raspberry character…"],[/bezow.*mango|mango meringue/,"Mango · beza","Mango · meringue","Lekka beza i soczysty, tropikalny akcent mango…","Light meringue with a juicy tropical mango accent…"]];const match=options.find(([pattern])=>pattern.test(name));return match?{notes:lang==="pl"?match[1]:match[2],teaser:lang==="pl"?match[3]:match[4]}:{notes:lang==="pl"?"Słodki wybór Atelier":"Atelier sweet selection",teaser:lang==="pl"?"Dotknij, aby poznać szczegóły tego deseru.":"Tap to discover this dessert."}}
function isChefCategory(category:Category|undefined){return (category?.pl??"").normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim().toLocaleLowerCase("pl").replace(/ł/g,"l")==="na slono"}
function isCapuccinoBannerCategory(category:Category|undefined){return category?.visualKind==="cakes"||category?.id==="cakes"}
