 "english breakfast":"/tea/english-breakfast.jpg","earl grey":"/tea/earl-grey.jpg","ctc assam":"/tea/ctc-assam.jpg","japanese sencha":"/tea/japanese-sencha.jpg","tropical green":"/tea/tropical-green.jpg","peppermint":"/tea/peppermint.jpg","spiced plum herbal":"/tea/spiced-plum.jpg","orange passion fruit":"/tea/orange-passion-fruit.jpg","peach fruit tea":"/tea/peach-fruit.jpg","strawberry kiwi fruit tea":"/tea/strawberry-kiwi.jpg","paris":"/tea/paris.jpg","hot cinnamon spice":"/tea/hot-cinnamon-spice.jpg","jasmine":"/tea/jasmine.jpg","mango fruit tea":"/tea/mango-fruit.jpg","mango friut tea":"/tea/mango-fruit.jpg","rooibos chai":"/tea/rooibos-chai.jpg"
