function teaImageFor(product:Product){const name=product.pl.normalize("NFD").replace(/[\u0300-\u036f]/g,"").trim().toLocaleLowerCase("pl");return teaImageByName[name]}
function isAlternativeCoffeeProduct(product:Product){return product.groupPl==="Kawy alternatywne"||product.groupEn==="Alternative coffee"}
function isAeropressMethod(product:Product|null){return Boolean(product&&/aero\s*press/i.test(`${product.pl} ${product.en}`))}
function isChemexMethod(product:Product|null){return Boolean(product&&/\bchemex\b/i.test(`${product.pl} ${product.en}`))}
function isDripMethod(product:Product|null){return Boolean(product&&/(?:\bdrip\b|\bv\s*60\b)/i.test(`${product.pl} ${product.en}`))}
function coffeeMethodImage(product:Product){return isChemexMethod(product)?"/coffee-methods/chemex.jpg":isAeropressMethod(product)?"/coffee-methods/aeropress.jpg":isDripMethod(product)?"/coffee-methods/drip.jpg":undefined}
function coffeeMethodImageClass(product:Product){return isChemexMethod(product)?"is-chemex":isAeropressMethod(product)?"is-aeropress":isDripMethod(product)?"is-drip":""}

