 const visibleImage=images.length?activeImage%images.length:0;
 const touchStartX=useRef<number|null>(null);
 const showImage=(index:number)=>setActiveImage((index+images.length)%images.length);
 const finishSwipe=(clientX:number)=>{if(touchStartX.current==null||images.length<2)return;const distance=clientX-touchStartX.current;touchStartX.current=null;if(Math.abs(distance)>42)showImage(visibleImage+(distance<0?1:-1))};
