function Options({lang,options,onSyrups}:{lang:Lang;options:CoffeeOption[];onSyrups?:()=>void}){const L=(pl:string,en:string)=>lang==="pl"?pl:en;return <aside className="options"><div><span>{L("Dopasuj swoją kawę","Make it yours")}</span><h2>{L("Mleko, moc, dodatki","Milk, strength, extras")}</h2></div><ul>{options.map(option=>{const syrup=isGenericFlavorSyrupOption(option.pl)&&onSyrups;return <li key={option.id} className={syrup?"is-syrup-option":""}>{syrup?<button type="button" onClick={onSyrups}><span>{option[lang]}</span><small>{L("wybierz smak","choose a flavour")}</small><strong>{option.price}{/\d/.test(option.price)?" zł":""}</strong></button>:<><span>{option[lang]}</span><strong>{option.price}{/\d/.test(option.price)?" zł":""}</strong></>}</li>})}</ul></aside>}
function FlavorSyrupBanner({lang,context,onOpen}:{lang:Lang;context:string;onOpen:()=>void}){const L=(pl:string,en:string)=>lang==="pl"?pl:en;const drink=context==="tea"?L("herbaty","your tea"):context==="matcha"?L("matchy","your matcha"):context==="cold"?L("lemoniady","your lemonade"):L("kawy","your coffee");return <button type="button" className="flavor-syrup-banner" onClick={onOpen}><span><small>LEŚNE ŻYCIE</small><b>{lang==="pl"?`Dodaj smak do ${drink}`:`Add flavour to ${drink}`}</b></span><em>{L("Wybierz dodatkowy syrop smakowy","Choose a flavoured syrup")}</em><strong>{L("Zobacz smaki","See flavours")} →</strong></button>}
function FlavorSyrupDialog({open,lang,syrups,onClose}:{open:boolean;lang:Lang;syrups:FlavorSyrup[];onClose:()=>void}){const L=(pl:string,en:string)=>lang==="pl"?pl:en;const addonPrice=syrups.find(item=>item.addonPrice)?.addonPrice;return <Dialog open={open} onOpenChange={next=>{if(!next)onClose()}}><DialogContent className="flavor-syrup-dialog" showCloseButton={false}><button type="button" className="wine-detail-close" onClick={onClose} aria-label={L("Zamknij wybór syropów","Close syrup selection")}><ModalCloseIcon/></button><header><span>LEŚNE ŻYCIE · {L("DODATKOWY SMAK","EXTRA FLAVOUR")}</span><DialogTitle>{L("Wybierz syrop do swojego napoju","Choose a syrup for your drink")}</DialogTitle><DialogDescription>{L("Poniżej pokazujemy smaki, które mamy obecnie na stanie. Powiedz kelnerowi, który wybierasz.","These are the flavours currently in stock. Tell your waiter which one you would like.")}</DialogDescription>{addonPrice&&<b>{L("Dodatek","Add-on")} + {addonPrice} zł</b>}</header><div className="flavor-syrup-grid">{syrups.map(syrup=><article key={syrup.id}>{syrup.image?<img src={syrup.image} alt={syrup[lang]}/>:<div className="flavor-syrup-placeholder"><span>LEŚNE</span><b>ŻYCIE</b></div>}<div><h3>{syrup[lang]}</h3>{(lang==="pl"?syrup.descriptionPl:syrup.descriptionEn||syrup.descriptionPl)&&<p>{lang==="pl"?syrup.descriptionPl:syrup.descriptionEn||syrup.descriptionPl}</p>}</div></article>)}</div><footer><p>{L("Pełne butelki tych syropów kupisz osobno w zakładce „Z PÓŁKI”.","Full bottles are also available separately in “From the shelf”.")}</p><button type="button" onClick={onClose}>{L("Wróć do karty","Back to menu")}</button></footer></DialogContent></Dialog>}
function AlternativeCoffeeBeans({lang,beans,methods}:{lang:Lang;beans:AlternativeCoffeeBean[];methods:Product[]}){
 const L=(pl:string,en:string)=>lang==="pl"?pl:en;
 const[selectedId,setSelectedId]=useState("");
 const[selectedMethodId,setSelectedMethodId]=useState("");
 const[previewOpen,setPreviewOpen]=useState(false);
 const[methodPreview,setMethodPreview]=useState<Product|null>(null);
 const methodKey=(method:Product)=>String(method.id??method.pl);
 const selected=beans.find(bean=>bean.id===selectedId)??null;
 const selectedMethod=methods.find(method=>methodKey(method)===selectedMethodId)??null;
 const chooseBean=(bean:AlternativeCoffeeBean)=>{setSelectedId(bean.id);setSelectedMethodId("");setPreviewOpen(true)};
 const chooseMethod=(method:Product)=>{setSelectedMethodId(methodKey(method));if(isAeropressMethod(method)||isChemexMethod(method)||isDripMethod(method))setMethodPreview(method)};
 const beanDescription=selected&&((lang==="pl"?selected.descriptionPl:selected.descriptionEn)||L("Opis pochodzenia i profilu smakowego tego ziarna zostanie wkrótce uzupełniony.","The origin and flavour profile for these beans will be added soon."));
 const aeropressStory=L(
  "AeroPress powstał z potrzeby zaparzenia jednej naprawdę dobrej filiżanki kawy. Inżynier i wynalazca Alan Adler rozpoczął eksperymenty w 2003 roku, badając wpływ czasu, temperatury i ciśnienia na smak naparu. Po dwóch latach i ponad 30 prototypach zaprezentował gotowe urządzenie podczas Coffee Fest Seattle w listopadzie 2005 roku. Metoda wykorzystuje ciśnienie powietrza, dzięki czemu parzenie jest szybkie, a kawa czysta, pełna smaku i mniej gorzka.",
  "AeroPress began with the search for one genuinely great cup of coffee. Engineer and inventor Alan Adler started experimenting in 2003, studying how time, temperature and pressure shape flavour. After two years and more than 30 prototypes, he introduced the finished brewer at Coffee Fest Seattle in November 2005. Air pressure makes the brew fast, clean and full-flavoured, with less bitterness."
 );
 const chemexStory=L(
  "Chemex zaprojektował i opatentował w 1941 roku chemik i wynalazca dr Peter Schlumbohm. Chciał połączyć prosty sposób parzenia kawy w domu z pięknym, funkcjonalnym przedmiotem inspirowanym szkłem laboratoryjnym i Bauhausem. Charakterystyczna klepsydra z borokrzemowego szkła oraz gruby filtr papierowy dają czysty, klarowny napar. Dziś Chemex jest ikoną wzornictwa obecną w kolekcjach muzealnych.",
  "CHEMEX was designed and patented in 1941 by chemist and inventor Dr Peter Schlumbohm. He wanted to combine simple home brewing with a beautiful, functional object inspired by laboratory glassware and Bauhaus design. Its borosilicate hourglass and thick bonded paper filter produce a clean, clear cup. Today CHEMEX is a design icon represented in museum collections."
 );
 const dripStory=L(
  "V60 to stożkowy dripper HARIO o kącie 60°, ze spiralnymi żebrami i jednym dużym otworem. Taka konstrukcja pozwala swobodnie sterować ekstrakcją tempem nalewania — szybsze daje łagodniejszy smak, a wolniejsze bardziej intensywny. Woda jest dolewana kontrolowanymi porcjami, spiralnym ruchem od środka. Papierowy filtr pomaga uzyskać czysty, klarowny napar, który wyraźnie pokazuje charakter wybranego ziarna.",
  "The HARIO V60 is a 60-degree cone-shaped dripper with spiral ribs and one large opening. Its design lets the pouring speed shape extraction — a faster pour makes a smoother cup, while a slower pour creates a richer flavour. Water is added in controlled stages, spiralling outward from the centre. The paper filter produces a clean, clear brew that reveals the character of the selected beans."
 );
 const chemexPreview=isChemexMethod(methodPreview);
 const dripPreview=isDripMethod(methodPreview);
 const methodStory=dripPreview?dripStory:chemexPreview?chemexStory:aeropressStory;
 const methodTitle=dripPreview?L("Drip V60 — pełna kontrola nad smakiem","V60 drip — full control over flavour"):chemexPreview?L("Chemex — czysty smak i ikona designu","CHEMEX — pure flavour and iconic design"):L("AeroPress — szybka metoda pełna smaku","AeroPress — fast brewing, full flavour");
 const methodVideo=dripPreview?"/drip-demo.mp4":chemexPreview?"/chemex-demo.mp4":"/aeropress-demo.mp4";
 const methodPoster=dripPreview?"/drip-demo-poster.jpg":chemexPreview?"/chemex-demo-poster.jpg":"/aeropress-demo-poster.jpg";
 const methodBrand=dripPreview?"":chemexPreview?"CHEMEX®":"AEROPRESS®";
 return <>
  <aside className="alternative-beans">
   <div className="alternative-beans-heading"><span>{L("Kawa przelewowa krok po kroku","Filter coffee, step by step")}</span><h3><b>1</b>{L("Wybierz ziarno","Choose your beans")}</h3><p>{L("Dotknij ziarna, aby zobaczyć jego opis i profil smakowy.","Tap a coffee to see its story and flavour profile.")}</p></div>
   <div className="alternative-beans-picker" role="group" aria-label={L("Dostępne ziarna","Available coffee beans")}>{beans.map(bean=><button type="button" key={bean.id} className={selected?.id===bean.id?"is-selected":""} aria-pressed={selected?.id===bean.id} onClick={()=>chooseBean(bean)}>{bean.image?<img src={bean.image} alt=""/>:<span className="alternative-bean-placeholder" aria-hidden="true">☕</span>}<span><strong>{bean[lang]}</strong><small>{L("Dotknij i poznaj ziarno","Tap to discover")}</small></span></button>)}</div>
   <div className={`alternative-method-step${selected?" is-ready":""}`}><div><span>{L("Krok 2","Step 2")}</span><h3><b>2</b>{L("Wybierz metodę parzenia","Choose the brewing method")}</h3><p>{selected?L(`Wybrane ziarno: ${selected.pl}`,`Selected beans: ${selected.en}`):L("Najpierw wybierz ziarno powyżej.","Choose your beans above first.")}</p></div><div className="alternative-method-picker" role="group" aria-label={L("Metody parzenia kawy","Coffee brewing methods")}>{methods.map(method=><button type="button" key={methodKey(method)} disabled={!selected} className={`${selectedMethodId===methodKey(method)?"is-selected":""}${coffeeMethodImage(method)?" has-image":""}`} aria-pressed={selectedMethodId===methodKey(method)} onClick={()=>chooseMethod(method)}>{coffeeMethodImage(method)&&<img className={coffeeMethodImageClass(method)} src={coffeeMethodImage(method)} alt=""/>}<span>{method[lang]}</span><strong>{method.price}{/\d/.test(method.price)?" zł":""}</strong></button>)}</div>{selected&&selectedMethod&&<p className="alternative-selection-summary"><span>{L("Twój wybór","Your selection")}</span><b>{selected[lang]} · {selectedMethod[lang]}</b><small>{L("Podaj ten wybór obsłudze przy zamówieniu.","Tell your server this selection when ordering.")}</small></p>}</div>
  </aside>
  <Dialog open={Boolean(selected&&previewOpen)} onOpenChange={open=>{if(!open)setPreviewOpen(false)}}><DialogContent className="wine-detail-dialog alternative-bean-dialog" showCloseButton={false}><button type="button" className="wine-detail-close" onClick={()=>setPreviewOpen(false)} aria-label={L("Zamknij opis ziarna","Close coffee bean details")}><ModalCloseIcon/></button><div className="wine-detail-copy"><span>ATELIER CAFÉ · {L("KAWY ALTERNATYWNE","FILTER COFFEE")}</span><DialogTitle>{selected?.[lang]}</DialogTitle><div className="shelf-detail-scroll"><DialogDescription>{beanDescription}</DialogDescription></div><div className="alternative-dialog-methods"><b>{L("Wybierz sposób przygotowania","Choose how it is brewed")}</b>{methods.map(method=><button type="button" key={methodKey(method)} className={`${selectedMethodId===methodKey(method)?"is-selected":""}${coffeeMethodImage(method)?" has-image":""}`} onClick={()=>chooseMethod(method)}>{coffeeMethodImage(method)&&<img className={coffeeMethodImageClass(method)} src={coffeeMethodImage(method)} alt=""/>}<span>{method[lang]}</span><strong>{method.price}{/\d/.test(method.price)?" zł":""}</strong></button>)}</div><div className="wine-detail-actions"><button type="button" onClick={()=>setPreviewOpen(false)}>{selectedMethod?L("Zatwierdź wybór","Confirm selection"):L("Wróć do wyboru","Back to selection")}</button></div></div><div className="wine-detail-visual alternative-bean-visual">{selected?.image?<img src={selected.image} alt={selected[lang]}/>:<div className="wine-detail-placeholder"><span>ATELIER CAFÉ</span><b>{L("Zdjęcie ziarna wkrótce","Bean photo coming soon")}</b></div>}{selectedMethod&&<div className="wine-detail-prices"><span>{selectedMethod[lang]}</span><strong>{selectedMethod.price}{/\d/.test(selectedMethod.price)?" zł":""}</strong></div>}</div></DialogContent></Dialog>
  <Dialog open={Boolean(methodPreview)} onOpenChange={open=>{if(!open)setMethodPreview(null)}}><DialogContent className="wine-detail-dialog coffee-method-detail-dialog" showCloseButton={false}><button type="button" className="wine-detail-close" onClick={()=>setMethodPreview(null)} aria-label={L("Zamknij podgląd metody","Close method preview")}><ModalCloseIcon/></button><div className="wine-detail-copy"><span>ATELIER CAFÉ · {L("POZNAJ METODĘ","DISCOVER THE METHOD")}</span><DialogTitle>{methodTitle}</DialogTitle><div className="shelf-detail-scroll"><DialogDescription>{methodStory}</DialogDescription>{selected&&<p className="coffee-method-selected-bean">{L("Wybrane ziarno","Selected beans")}: <b>{selected[lang]}</b></p>}</div></div><div className="wine-detail-visual alternative-bean-visual coffee-method-detail-visual"><video className="alternative-method-video" src={methodVideo} poster={methodPoster} autoPlay muted loop playsInline preload="metadata" aria-label={methodPreview?L(`Parzenie kawy metodą ${methodPreview.pl}`,`Brewing coffee with ${methodPreview.en}`):undefined}/>{methodBrand&&<span className="alternative-method-media-credit">{methodBrand}</span>}{methodPreview&&<div className="wine-detail-prices"><span>{methodPreview[lang]}</span><strong>{methodPreview.price}{/\d/.test(methodPreview.price)?" zł":""}</strong></div>}</div></DialogContent></Dialog>
 </>
}
function TakeHomeCoffee({products,lang,onOpen}:{products:Product[];lang:Lang;onOpen:(product:Product)=>void}){const L=(pl:string,en:string)=>lang==="pl"?pl:en;return <aside className="take-home-coffee"><div className="take-home-heading"><span>{L("Z naszej półki","From our shelf")}</span><h2>{L("Zabierz naszą kawę do domu","Take our coffee home")}</h2><p>{L("Ziarna, które możesz kupić na miejscu.","Coffee beans available to buy in the café.")}</p></div><div className="take-home-list">{products.map(product=><ProductCard key={product.id??product.pl} product={product} lang={lang} onAllergens={()=>undefined} onOpen={onOpen}/>)}</div></aside>}
function Welcome({lang,go,promos}:{lang:Lang;go:(id:string)=>void;promos:Product[]}){const L=(pl:string,en:string)=>lang==="pl"?pl:en;return <section className={promos.length?"welcome":"welcome no-promos"}>
 <div className="welcome-art" aria-label={L("Marta Banaszek w atelier-café","Marta Banaszek at atelier-café")} role="img"></div><div className="welcome-copy"><img className="welcome-logo" src="/logo-cafe.png" alt="Marta Banaszek atelier-café"/><p>ATELIER · CAFÉ</p><h1>{L("Witajcie w moim atelier-café","Welcome to my atelier-café")}</h1><blockquote>{L("To miejsce, gdzie spotykają się smak, styl i pasja do tworzenia mody. Mam nadzieję, że czas spędzony tu będzie pełen przyjemności i inspiracji.","A place where flavour, style and a passion for fashion come together. I hope your time here will be filled with pleasure and inspiration.")}</blockquote><div className="welcome-buttons"><button onClick={()=>go("food")}>{L("Odkryj menu","Explore menu")} <span>→</span></button><button onClick={()=>go("events")}>{L("Wydarzenia w Atelier","Events at Atelier")}</button></div></div>
 {promos.length>0&&<div className="recommend"><div className="recommend-label"><p>{L("Polecamy dziś","Today’s selection")}</p><span>{L("Wybrane przez Atelier","Selected by Atelier")}</span></div><div className="recommend-items">{promos.map(product=><button className="recommend-item" key={product.id??product.pl} onClick={()=>go(product.category)}><span><h2>{product[lang]}</h2><small>{lang==="pl"?product.descPl:product.descEn}</small></span><strong>{product.price}{/\d/.test(product.price)?" zł":""}</strong><i>→</i></button>)}</div></div>}
 </section>}
function Events({lang,events,loading,unavailable,stale}:{lang:Lang;events:UpcomingEvent[];loading:boolean;unavailable:boolean;stale:boolean}){
 const L=(pl:string,en:string)=>lang==="pl"?pl:en;
 const[selected,setSelected]=useState<UpcomingEvent|null>(null);const[detail,setDetail]=useState<EventDetail|null>(null);const[detailLoading,setDetailLoading]=useState(false);const[detailUnavailable,setDetailUnavailable]=useState(false);
 // eslint-disable-next-line react-hooks/set-state-in-effect
 useEffect(()=>{if(!selected){setDetail(null);setDetailUnavailable(false);return}const controller=new AbortController();setDetail(null);setDetailLoading(true);setDetailUnavailable(false);fetch(`/api/events/${encodeURIComponent(selected.id)}?menu-refresh=${Date.now()}`,{signal:controller.signal,cache:"no-store",headers:{"cache-control":"no-cache"}}).then(async response=>{if(!response.ok)throw new Error("detail unavailable");return response.json()}).then((body:EventDetail)=>setDetail(body)).catch(()=>{if(!controller.signal.aborted)setDetailUnavailable(true)}).finally(()=>{if(!controller.signal.aborted)setDetailLoading(false)});return()=>controller.abort()},[selected]);
 return <><section className="events sheet"><div className="events-heading"><p>ATELIER CAFÉ · {L("KALENDARZ","CALENDAR")}</p><h1>{L("Nadchodzące wydarzenia","Upcoming events")}</h1><span>{L("Dotknij wydarzenia, aby poznać szczegóły","Tap an event to read more")}</span></div>
  {loading&&events.length===0?<div className="events-status" role="status">{L("Pobieramy aktualny kalendarz…","Loading the current calendar…")}</div>:events.length>0?<div className="events-list">{events.map(item=><button type="button" className="event-card" key={item.id} onClick={()=>setSelected(item)} aria-label={`${L("Pokaż opis","Show details")}: ${lang==="pl"?item.title:item.titleEn||item.title}`}><span className="event-date"><strong>{item.day}</strong><span>{lang==="pl"?item.month:eventMonthsEn[item.month]||item.month}</span><small>{item.time}</small></span><span className="event-details"><span>{lang==="pl"?item.kind:item.kindEn||item.kind}</span><strong>{lang==="pl"?item.title:item.titleEn||item.title}</strong></span><span className="event-order">{L("Zamów bilet do stolika","Order a ticket at your table")}</span></button>)}</div>:<div className="events-status"><b>{L("Nie udało się teraz pobrać kalendarza.","The calendar is temporarily unavailable.")}</b><span>{L("Zapytaj obsługę o aktualne wydarzenia.","Ask our staff about current events.")}</span></div>}
  {(stale||unavailable)&&events.length>0&&<p className="events-warning">{L("Pokazujemy ostatnio pobrany repertuar.","Showing the most recently fetched programme.")}</p>}
 </section><Dialog open={Boolean(selected)} onOpenChange={open=>{if(!open)setSelected(null)}}><DialogContent className="event-preview" showCloseButton={false}><button type="button" className="event-preview-close" onClick={()=>setSelected(null)} aria-label={L("Zamknij opis wydarzenia","Close event details")}><ModalCloseIcon/></button><div className="event-preview-copy"><span>{selected&&(lang==="pl"?selected.kind:selected.kindEn||selected.kind)}</span><DialogTitle>{selected&&(lang==="pl"?selected.title:selected.titleEn||selected.title)}</DialogTitle><p className="event-preview-meta">{selected&&`${selected.day} ${lang==="pl"?selected.month:eventMonthsEn[selected.month]||selected.month} · ${selected.time}`}</p><div className="event-preview-scroll"><DialogDescription className="event-preview-description">{detailLoading?L("Pobieramy opis wydarzenia…","Loading event details…"):detailUnavailable?L("Opis jest chwilowo niedostępny. Zapytaj obsługę o szczegóły wydarzenia.","The description is temporarily unavailable. Ask our staff for event details."):detail?(lang==="pl"?detail.descriptionPl:detail.descriptionEn||detail.descriptionPl):""}</DialogDescription></div><button type="button" className="event-preview-return" onClick={()=>setSelected(null)}>{L("Wróć do wydarzeń","Back to events")}</button></div><div className="event-preview-ticket" role="button" tabIndex={0} onClick={()=>setSelected(null)} onKeyDown={event=>{if(event.key==="Enter"||event.key===" ")setSelected(null)}}>{detail?.image&&<img src={detail.image} alt=""/>}<div><span>ATELIER CAFÉ</span><b>{L("Bilet","Ticket")}</b><strong>{selected?.day}</strong><em>{selected&&(lang==="pl"?selected.month:eventMonthsEn[selected.month]||selected.month)} · {selected?.time}</em><small>{L("Zamów u obsługi do stolika","Order from your server at the table")}</small></div></div></DialogContent></Dialog></>
}
function LoyaltyRegistration({lang}:{lang:Lang}){
 const L=(pl:string,en:string)=>lang==="pl"?pl:en;const[submitting,setSubmitting]=useState(false);const[result,setResult]=useState<{kind:"success"|"error";message:string}|null>(null);
 const submit=async(event:FormEvent<HTMLFormElement>)=>{event.preventDefault();if(submitting)return;setSubmitting(true);setResult(null);const element=event.currentTarget;const form=new FormData(element);try{const response=await fetch("/api/loyalty/register",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({firstName:form.get("firstName"),lastName:form.get("lastName"),email:form.get("email"),phone:form.get("phone"),barcode:form.get("barcode"),marketingConsent:form.get("marketingConsent")==="on"})});const body=await response.json().catch(()=>({})) as {ok?:boolean;error?:string};if(!response.ok||!body.ok){const englishError=response.status===422?"The card could not be registered. Check the details and make sure it has not already been registered.":response.status===503?"Registration is temporarily unavailable. Try again in a moment or ask our staff for help.":"Check all fields and the card code, then try again.";throw new Error(lang==="pl"&&body.error?body.error:englishError)}element.reset();setResult({kind:"success",message:L("Karta została zarejestrowana. Dziękujemy — witamy w MB Atelier Café!","Your card has been registered. Thank you — welcome to MB Atelier Café!")})}catch(error){setResult({kind:"error",message:error instanceof Error?error.message:L("System rejestracji jest chwilowo niedostępny.","Registration is temporarily unavailable.")})}finally{setSubmitting(false)}};
 return <section className="loyalty-page"><div className="loyalty-backdrop" aria-hidden="true"/><div className="loyalty-layout"><div className="loyalty-intro"><span>MB ATELIER CAFÉ</span><h1>{L("Karta, która zostaje z Tobą","A card that stays with you")}</h1><p>{L("Zarejestruj swoją fizyczną kartę MB. Wkrótce w tym miejscu opowiemy również o wszystkich korzyściach programu.","Register your physical MB card. Soon, this space will also introduce all programme benefits.")}</p></div><div className="loyalty-card"><img src="/logo-cafe.png" alt="Marta Banaszek atelier-café"/><span>{L("Rejestracja karty","Card registration")}</span><h2>{L("Dołącz do programu Atelier Café","Join the Atelier Café programme")}</h2><p>{L("Wpisz dane i kod z fizycznej karty.","Enter your details and the code printed on your physical card.")}</p><form onSubmit={submit}><div className="loyalty-fields"><label>{L("Imię","First name")}<input name="firstName" autoComplete="given-name" maxLength={100} required/></label><label>{L("Nazwisko","Last name")}<input name="lastName" autoComplete="family-name" maxLength={100} required/></label><label>{L("E-mail","Email")}<input name="email" type="email" inputMode="email" autoComplete="email" maxLength={100} required/></label><label>{L("Telefon","Phone")}<input name="phone" type="tel" inputMode="tel" autoComplete="tel" maxLength={20} required/></label></div><label className="loyalty-code">{L("Kod karty","Card code")}<input name="barcode" autoCapitalize="characters" autoCorrect="off" spellCheck={false} maxLength={60} placeholder="MB-12" pattern="[Mm][Bb]-[0-9]+" required/><small>{L("Format: MB-numer, na przykład MB-12.","Format: MB-number, for example MB-12.")}</small></label><label className="loyalty-consent"><input name="marketingConsent" type="checkbox" required/><span>{L("Wyrażam zgodę na kontakt i przesyłanie treści marketingowych dla firmy Centrum Concept Sp. z o.o. Marta Banaszek Atelier-Cafe.","I consent to being contacted and receiving marketing communications from Centrum Concept Sp. z o.o. Marta Banaszek Atelier-Cafe.")}</span></label>{result&&<p className={`loyalty-result is-${result.kind}`} role={result.kind==="error"?"alert":"status"}>{result.message}</p>}<button type="submit" disabled={submitting}>{submitting?L("Rejestruję…","Registering…"):L("Zarejestruj kartę","Register card")}</button><small className="loyalty-privacy">{L("Po wysłaniu dane są bezpiecznie przekazywane do systemu obsługującego program kart MB Atelier Café.","When submitted, your details are securely passed to the system operating the MB Atelier Café card programme.")}</small></form></div></div></section>
}
